    public static function landing(array $enhancements, array $updates, ?array $user, string $csrf): never
    {
        self::start('Premium Game Enhancements', 'Game-specific enhancement software for competitive players, delivered through the Pericles platform.', $user, $csrf, 'home', $updates !== []);
        echo '<main><section class="commerce-hero"><div class="commerce-hero-inner"><span class="system-pill"><i></i> PERICLES PLATFORM</span><h1>Premium Game<br><em>Enhancements</em></h1><p>Game-specific enhancement software for competitive players, delivered through the Pericles platform.</p><div class="hero-actions"><a class="btn btn-primary btn-large" href="'.self::url('/enhancements').'">Explore Enhancements</a><a class="btn btn-outline btn-large" href="#how-it-works">How It Works</a></div><div class="commerce-trust"><span>Live product status</span><span>Regular updates</span><span>Customer support</span><span>Secure checkout</span></div></div></section>';
        echo '<section class="commerce-section"><div class="section-intro"><span>AVAILABLE ENHANCEMENTS</span><h2>Choose your game</h2><p>Compare live status, product details, and Access Plans.</p></div>'; self::cards($enhancements,$csrf); echo '</section>';
        echo '<section class="commerce-section commerce-muted" id="how-it-works"><div class="section-intro"><span>HOW IT WORKS</span><h2>Purchase. Download. Activate.</h2></div><div class="steps-grid"><article><b>01</b><h3>Choose Your Access</h3><p>Select an Enhancement and a timed or Lifetime Access Plan.</p></article><article><b>02</b><h3>Secure Checkout</h3><p>Sign in or create your account without losing your selected plan.</p></article><article><b>03</b><h3>Activate When Ready</h3><p>Your timed Access begins on first activation. Activate within seven days.</p></article></div></section>';
        if($updates!==[]){echo '<section class="commerce-section"><div class="section-intro"><span>LATEST UPDATES</span><h2>Recently published</h2></div><div class="update-list">';foreach(array_slice($updates,0,4) as $u)self::update($u);echo '</div></section>';}
        echo '<section class="commerce-section faq-section" id="faq"><div class="section-intro"><span>FAQ</span><h2>Before you get started</h2></div><div class="faq-list"><details><summary>When does timed Access begin?</summary><p>It begins when you first activate the Enhancement. Activation must occur within seven days of purchase.</p></details><details><summary>Is my selected plan kept during sign in?</summary><p>Yes. Your checkout selection survives sign in and account creation.</p></details><details><summary>What happens during product downtime?</summary><p>When downtime compensation is enabled for an incident, the recorded duration is added back to affected timed Access once service returns.</p></details></div></section><section class="final-cta"><h2>Ready to choose your Enhancement?</h2><a class="btn btn-primary btn-large" href="'.self::url('/enhancements').'">Explore Enhancements</a></section></main>';
        self::end($user,$updates!==[]);
    }

    public static function catalog(array $enhancements, ?array $user, string $csrf): never
    {
        self::start('Enhancements','Browse Pericles Game Enhancements, previews, features, and Access Plans.',$user,$csrf,'enhancements');
        echo '<main class="catalog-main"><section class="catalog-heading"><span>GAME ENHANCEMENTS</span><h1>Built for your game.</h1><p>Explore product previews, feature lists, compatibility, and live Access Plans.</p></section>';self::cards($enhancements,$csrf);echo '</main>';self::end($user);
    }

    public static function product(array $product, ?array $user, string $csrf, ?string $message=null): never
    {
        $game=(string)$product['game_name'];$name=trim((string)$product['product_name'])?:$game.' Enhancement';
        if(!str_contains(strtolower($name),'enhancement'))$name.=' Enhancement';
        $title=trim((string)($product['seo_title']??''))?:$name.' | Pericles';
        $description=trim((string)($product['seo_description']??''))?:'Explore the Pericles '.$game.' Game Enhancement, available features, preview media, pricing, compatibility and Access Plans.';
        self::start($title,$description,$user,$csrf,'enhancements',($product['changelog']??[])!==[]);
        $status=(string)$product['commercial_status'];$from=$product['minimum_price_cents']===null?'Plans unavailable':'From '.self::money((int)$product['minimum_price_cents'],(string)($product['plans'][0]['currency']??'EUR'));
        echo '<main>'.($message===null?'':'<div class="public-alert">'.self::e($message).'</div>').'<nav class="product-anchor-nav"><a href="#overview">Overview</a>'.(($product['media']??[])===[]?'':'<a href="#preview">Preview</a>').(($product['features']??[])===[]?'':'<a href="#features">Features</a>').'<a href="#pricing">Pricing</a>'.(($product['faqs']??[])===[]?'':'<a href="#product-faq">FAQ</a>').'</nav>';
        echo '<section class="product-hero" id="overview"><div class="product-summary"><a class="eyebrow-link" href="'.self::url('/enhancements').'">← All Enhancements</a><span class="product-game-label">'.self::e(strtoupper($game)).'</span><h1>'.self::e($name).'</h1><p>'.self::e(trim((string)($product['product_short_description']??$product['description']??$product['short_description']))).'</p><div class="product-facts"><span class="commerce-status status-'.self::e($status).'"><i></i>'.self::statusLabel($status).'</span>'.(empty($product['latest_version'])?'':'<span>Version '.self::e((string)$product['latest_version']).'</span>').(empty($product['latest_release'])?'':'<span>Updated '.self::date((string)$product['latest_release']).'</span>').'<strong>'.self::e($from).'</strong></div>';
        self::owned($product);
        echo '<div class="hero-actions"><a class="btn btn-primary" href="#pricing">Buy Now</a>'.(($product['features']??[])===[]?'':'<a class="btn btn-outline" href="#features">View Features</a>').'</div></div><div class="product-cover">'.self::cover($product,true).'</div></section>';

        if(($product['media']??[])!==[])self::carousel($product['media'],$game);
        $highlights=[];foreach($product['features']??[] as $category)foreach($category['items'] as $feature)if(!empty($feature['highlighted']))$highlights[]=$feature+['category'=>$category['name']];
        if($highlights!==[]){echo '<section class="commerce-section compact-section"><div class="section-intro"><span>FEATURE HIGHLIGHTS</span><h2>At a glance</h2></div><div class="highlight-grid">';foreach(array_slice($highlights,0,8) as $f)echo '<article><small>'.self::e((string)$f['category']).'</small><h3>'.self::e((string)$f['name']).'</h3>'.(empty($f['description'])?'':'<p>'.self::e((string)$f['description']).'</p>').'</article>';echo '</div></section>';}
        if(($product['features']??[])!==[])self::featureList($product['features']);
        self::included($product);
        echo '<section class="commerce-section commerce-muted" id="pricing"><div class="section-intro"><span>ACCESS PLANS</span><h2>Choose your Access</h2><p>Secure checkout · No hidden fees</p></div>';self::plans($product,$csrf);echo '<aside class="access-start"><strong>Your time starts when you do.</strong><span>Timed Access Plans begin when you first activate the Enhancement. Activate within 7 days of purchase.</span><a href="#product-faq">Learn more</a></aside></section>';
        self::compatibility($product);
        echo '<section class="commerce-section compact-section"><div class="section-intro"><span>HOW IT WORKS</span><h2>Get started in five steps</h2></div><ol class="product-steps"><li><b>01</b>Purchase Your Access</li><li><b>02</b>Download Pericles</li><li><b>03</b>Sign In</li><li><b>04</b>Activate Your Enhancement</li><li><b>05</b>Access Documentation &amp; Updates</li></ol></section>';
        if(($product['changelog']??[])!==[]){$u=$product['changelog'][0];echo '<section class="commerce-section compact-section"><div class="section-intro"><span>LATEST UPDATE</span><h2>Version '.self::e((string)$u['version']).'</h2><p>'.self::date((string)$u['published_at']).'</p></div><article class="latest-update">'.nl2br(self::e((string)$u['summary'])).'</article></section>';}
        if(($product['faqs']??[])!==[]){echo '<section class="commerce-section faq-section" id="product-faq"><div class="section-intro"><span>FAQ</span><h2>Questions about '.self::e($name).'</h2></div><div class="faq-list">';foreach($product['faqs'] as $faq)echo '<details><summary>'.self::e((string)$faq['question']).'</summary><p>'.self::e((string)$faq['answer']).'</p></details>';echo '</div></section>';}
        echo '<section class="final-cta"><span>READY TO GET STARTED?</span><h2>'.self::e($name).'</h2><p>'.self::e($from).'</p><a class="btn btn-primary btn-large" href="#pricing">Choose Your Access</a></section><p class="product-disclaimer">Pericles is an independent third-party product and is not affiliated with or endorsed by the publishers of the games listed on this website.</p></main>';
        self::end($user,($product['changelog']??[])!==[]);
    }

    public static function checkout(array $checkout,?array $user,string $csrf,string $token,?array $order,?array $stripe,?string $message=null):never
    {
        self::start('Secure Checkout','Review and complete your Pericles order.',$user,$csrf,'',true,$stripe!==null);echo '<main class="checkout-main"><section class="checkout-heading"><span>SECURE CHECKOUT</span><h1>Order Summary</h1></section>'.($message===null?'':'<div class="checkout-message">'.self::e($message).'</div>').'<div class="checkout-grid"><section class="checkout-card"><div class="checkout-product">'.self::cover($checkout,false).'<div><small>Enhancement</small><h2>'.self::e((string)$checkout['game_name']).' Enhancement</h2><span>'.self::e((string)$checkout['plan_name']).' Access</span></div></div><dl><div><dt>Access begins</dt><dd>First activation</dd></div><div><dt>Total</dt><dd>'.self::money((int)$checkout['price_cents'],(string)$checkout['currency']).'</dd></div></dl></section><aside class="checkout-card checkout-action">';
        if($order!==null){$status=(string)$order['status'];echo '<span class="commerce-status status-'.self::e($status).'"><i></i>'.self::e(ucfirst($status)).'</span><h2>Order '.self::e((string)$order['order_number']).'</h2>';if($status==='paid')echo '<p>Payment confirmed. Your Enhancement is available.</p><a class="btn btn-primary btn-block" href="'.self::url('/products').'">Open My Enhancements</a>';elseif(!empty($order['payment_processing']))echo '<p>Stripe is finalizing your payment. Access appears only after the signed confirmation is received.</p><a class="btn btn-primary btn-block" href="'.self::url('/checkout/'.rawurlencode($token)).'">Refresh Payment Status</a>';elseif($status==='pending'&&$stripe!==null)echo '<p>Pay securely without leaving Pericles.</p><div class="stripe-payment" data-stripe-payment data-publishable-key="'.self::e((string)$stripe['publishable_key']).'" data-session-url="'.self::e((string)$stripe['session_url']).'" data-csrf="'.self::e($csrf).'"><form data-stripe-payment-form><div class="stripe-element-loading" data-stripe-loading>Loading secure payment form…</div><div data-stripe-element></div><p class="stripe-payment-error" data-stripe-error role="alert" hidden></p><button class="btn btn-primary btn-block" type="submit" data-stripe-submit disabled><span data-stripe-button-text>Pay '.self::money((int)$order['amount_cents'],(string)$order['currency']).'</span><span class="stripe-spinner" aria-hidden="true"></span></button></form><small class="stripe-secure-note">Payment details are encrypted and sent directly to Stripe. Pericles never receives your card number.</small></div>';elseif($status==='pending')echo '<p>Online payment is not configured. No charge was attempted.</p><a class="btn btn-outline btn-block" href="'.self::url('/support').'">Contact Support</a>';else echo '<p>This order is no longer payable.</p><a class="btn btn-outline btn-block" href="'.self::url('/enhancements').'">Choose Another Plan</a>';}elseif($user===null)echo '<h2>Continue with your account</h2><p>Your selected plan is saved.</p><a class="btn btn-primary btn-block" href="'.self::url('/login').'">Sign In</a><a class="btn btn-outline btn-block" href="'.self::url('/register').'">Create Account</a>';else echo '<h2>Confirm Your Order</h2><p>Access begins on first activation.</p><form method="post" action="'.self::url('/checkout/'.rawurlencode($token).'/order').'"><input type="hidden" name="csrf" value="'.self::e($csrf).'"><label class="consent"><input type="checkbox" name="immediate_delivery" value="1" required><span>I request immediate digital delivery and accept the applicable Terms of Sale.</span></label><button class="btn btn-primary btn-block" type="submit">Create Order</button></form>';
        echo '</aside></div></main>';self::end($user);
    }

    public static function support(?array $user,string $csrf,?string $message=null,?string $error=null):never
    {
        self::start('Support','Get help with Pericles Enhancements, Access, payments, and Authorized Devices.',$user,$csrf,'support');echo '<main class="support-main"><section class="catalog-heading"><span>PERICLES SUPPORT</span><h1>How Can We Help?</h1><p>Choose a topic or send a support request. Account context is attached automatically when you are signed in.</p></section><div class="support-categories">';foreach([['Getting Started','Account setup and first steps.'],['Installation','Launcher and installation help.'],['Account & Access','Access Plans and account questions.'],['Payments','Orders, payments, and billing.'],['Authorized Device','Device activation and reset.'],['Enhancement Issues','Product-specific assistance.'],['Documentation','Guides and configuration help.']] as [$t,$d])echo '<article><h2>'.self::e($t).'</h2><p>'.self::e($d).'</p></article>';echo '</div><section class="support-contact"><div><span>CONTACT SUPPORT</span><h2>Send a request</h2><p>Never include passwords, payment card details, or other secrets.</p>'.($user===null?'':'<a class="btn btn-outline" href="'.self::url('/account/support').'">View My Tickets</a>').'</div><form method="post" enctype="multipart/form-data" action="'.self::url('/support').'"><input type="hidden" name="csrf" value="'.self::e($csrf).'">'.($user===null?'<label>Email Address<input class="field" type="email" name="email" required autocomplete="email" placeholder="you@example.com"></label>':'<div class="support-account">Signed in as <strong>'.self::e((string)$user['email']).'</strong></div>').'<label>Category<select class="field" name="category" required><option value="account">Account &amp; Access</option><option value="installation">Installation</option><option value="payment">Payments</option><option value="device">Authorized Device</option><option value="product">Enhancement Issue</option><option value="other">Other</option></select></label><label>Priority<select class="field" name="priority" data-ticket-priority><option value="low">Low</option><option value="normal" selected>Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select><small class="urgent-warning" data-urgent-warning hidden>Use Urgent only for missing paid Access, critical security, or a major commercial access failure.</small></label><label>Subject<input class="field" name="subject" maxlength="180" required></label><label>Message<textarea class="field" name="message" minlength="10" maxlength="10000" rows="7" required></textarea></label><label>Attachments <small>Optional · PNG, JPG, WebP, GIF, PDF or text · 5 MB each</small><input class="field" type="file" name="attachments[]" multiple accept="image/png,image/jpeg,image/webp,image/gif,application/pdf,text/plain"></label><button class="btn btn-primary" type="submit">Contact Support</button></form></section>'.($message===null?'':'<div class="public-alert success">'.self::e($message).'</div>').($error===null?'':'<div class="public-alert">'.self::e($error).'</div>').'</main>';self::end($user);
    }

