    {
        self::start((string)$content['title'],(string)$content['title'].' for the Pericles platform.',$user,$csrf,'');echo '<main class="legal-main"><a class="eyebrow-link" href="'.self::url('/').'">← Back to Pericles</a><span>LEGAL · VERSION '.self::e((string)$content['version']).'</span><h1>'.self::e((string)$content['title']).'</h1><article>'.nl2br(self::e((string)$content['body'])).'</article><small>Last updated '.self::date((string)$content['updated_at']).'</small></main>';self::end($user);
    }

    public static function status(array $overview,?array $user,string $csrf):never
    {
        self::start('Service Status','Current Pericles platform and Enhancement status.',$user,$csrf,'status');echo '<main class="catalog-main"><section class="catalog-heading"><span>SERVICE STATUS</span><h1>Current availability</h1><p>No synthetic uptime or unverified availability data.</p></section><div class="status-board">';foreach($overview['services']??[] as $s)self::statusRow((string)$s['name'],(string)$s['status'],$s['incident']??null,$s['updated_at']??null);foreach($overview['games']??[] as $g)self::statusRow((string)$g['name'].' Enhancement',(string)$g['commercial_status'],$g['incident']??null,$g['status_updated_at']??null,$g);if(($overview['services']??[])===[]&&($overview['games']??[])===[])echo '<div class="catalog-empty">No service status has been published.</div>';echo '</div><section class="recent-incidents"><h2>Recent Incidents</h2>';
        if(($overview['maintenance']??[])===[])echo '<p>No resolved incidents have been published.</p>';else foreach($overview['maintenance'] as $i)echo '<article><strong>'.self::e((string)$i['game_name']).'</strong><span>'.self::e((string)($i['reason']??'Maintenance')).'</span><time>'.self::date((string)$i['ended_at']).'</time></article>';echo '</section></main>';self::end($user);
    }

    public static function changelog(array $updates,array $enhancements,?array $user,string $csrf):never
    {self::start('Changelog','Published Pericles Enhancement updates.',$user,$csrf,'changelog',$updates!==[]);echo '<main class="catalog-main"><section class="catalog-heading"><span>CHANGELOG</span><h1>Product Updates</h1><p>Only real, published release notes appear here.</p></section><div class="update-list">';foreach($updates as $u)self::update($u);if($updates===[])echo '<div class="catalog-empty">No public release has been published yet.</div>';echo '</div></main>';self::end($user,$updates!==[]);}

    private static function cards(array $items,string $csrf):void
    {echo '<div class="enhancement-grid">';foreach($items as $i){$status=(string)($i['commercial_status']??'unavailable');$slug=(string)$i['game_slug'];$name=trim((string)($i['product_name']??''))?:$i['game_name'].' Enhancement';if(!str_contains(strtolower($name),'enhancement'))$name.=' Enhancement';echo '<article class="enhancement-card"><a class="enhancement-cover" href="'.self::url('/enhancements/'.$slug).'">'.self::cover($i,true).'<span class="commerce-status status-'.self::e($status).'"><i></i>'.self::statusLabel($status).'</span></a><div><small>'.self::e(strtoupper((string)$i['game_name'])).'</small><h3>'.self::e($name).'</h3><p>'.self::e(trim((string)($i['product_short_description']??$i['description']??''))).'</p><div class="card-price">'.($i['minimum_price_cents']===null?'Plans unavailable':'From <strong>'.self::money((int)$i['minimum_price_cents'],(string)($i['plans'][0]['currency']??'EUR')).'</strong>').'</div><footer><a class="btn btn-outline" href="'.self::url('/enhancements/'.$slug).'">View Details</a>';if(($i['plans']??[])!==[]&&!empty($i['can_purchase'])){echo '<details class="quick-buy"><summary class="btn btn-primary">Buy Now</summary><div><strong>Choose Your Access</strong>';foreach($i['plans'] as $p)echo '<form method="post" action="'.self::url('/checkout/start').'"><input type="hidden" name="csrf" value="'.self::e($csrf).'"><input type="hidden" name="product_slug" value="'.self::e($slug).'"><input type="hidden" name="plan_id" value="'.(int)$p['id'].'"><button type="submit"><span>'.self::e((string)$p['name']).(!empty($p['badge'])?' <small>'.self::e((string)$p['badge']).'</small>':'').'</span><b>'.self::money((int)$p['effective_price_cents'],(string)$p['currency']).'</b></button></form>';echo '</div></details>';}echo '</footer></div></article>';}if($items===[])echo '<div class="catalog-empty">No public Enhancement is currently listed.</div>';echo '</div>';}

    private static function carousel(array $media,string $game):void
    {echo '<section class="commerce-section product-preview" id="preview"><div class="section-intro"><span>PRODUCT PREVIEW</span><h2>See the Enhancement</h2></div><div class="media-carousel" data-media-carousel tabindex="0"><div class="media-stage">';foreach($media as $index=>$m){$type=(string)$m['media_type'];echo '<figure class="media-slide'.($index===0?' active':'').'" data-media-slide="'.$index.'">';if($type==='video')echo '<video controls preload="none" poster="'.self::e((string)($m['poster_url']??'')).'" data-src="'.self::e((string)$m['url']).'"></video>';else echo '<button type="button" data-media-lightbox aria-label="Open image in full screen"><img '.($index===0?'':'loading="lazy" ').'src="'.self::e((string)$m['url']).'" alt="'.self::e((string)($m['alt_text']?:$game.' Enhancement preview')).'"></button>';if(!empty($m['title']))echo '<figcaption>'.self::e((string)$m['title']).'</figcaption>';echo '</figure>';}echo '<button class="media-arrow prev" type="button" data-media-prev aria-label="Previous media">‹</button><button class="media-arrow next" type="button" data-media-next aria-label="Next media">›</button><span class="media-counter"><b data-media-current>1</b> / '.count($media).'</span></div><div class="media-thumbnails">';foreach($media as $index=>$m){$thumb=trim((string)($m['thumbnail_url']??$m['poster_url']??$m['url']));echo '<button type="button" class="'.($index===0?'active':'').'" data-media-thumb="'.$index.'" aria-label="Show media '.($index+1).'">'.(((string)$m['media_type']==='video')?'<span>▶</span>':'<img loading="lazy" src="'.self::e($thumb).'" alt="">').'</button>';}echo '</div></div><dialog class="media-lightbox" data-media-dialog><button type="button" data-media-dialog-close aria-label="Close full screen">×</button><img alt=""></dialog></section>';}

    private static function featureList(array $categories):void
    {echo '<section class="commerce-section compact-section" id="features"><div class="section-intro"><span>FULL FEATURE LIST</span><h2>Explore every public feature</h2></div><div class="feature-accordion">';foreach($categories as $index=>$c){echo '<details'.($index===0?' open':'').'><summary><span><strong>'.self::e((string)$c['name']).'</strong>'.(empty($c['description'])?'':'<small>'.self::e((string)$c['description']).'</small>').'</span><b>'.count($c['items']).' Features</b></summary><ul>';foreach($c['items'] as $f)echo '<li><strong>'.self::e((string)$f['name']).'</strong>'.(empty($f['description'])?'':'<span>'.self::e((string)$f['description']).'</span>').'</li>';echo '</ul></details>';}echo '</div></section>';}

    private static function included(array $product):void
    {$items=[];$configured=json_decode((string)($product['included_items_json']??''),true);if(is_array($configured))$items=array_values(array_filter($configured,'is_string'));if($items===[]){$items=['Full Enhancement Access','Pericles Launcher','Product Updates','Customer Support','Downtime Compensation'];if(($product['documents']??[])!==[])$items[]='Product Documentation';}echo '<section class="commerce-section compact-section included-section"><div class="section-intro"><span>WHAT’S INCLUDED</span><h2>Included With Every Plan</h2></div><ul>';foreach($items as $item)echo '<li><i>✓</i>'.self::e($item).'</li>';echo '</ul></section>';}

    private static function plans(array $product,string $csrf):void
    {
        $plans=$product['plans']??[];$default=null;$defaultPlan=null;
        foreach($plans as $plan)if((int)($plan['duration_days']??0)===30){$default=(int)$plan['id'];$defaultPlan=$plan;break;}
        if($default===null&&$plans!==[]){$default=(int)$plans[0]['id'];$defaultPlan=$plans[0];}
        echo '<div class="selectable-plans" data-plan-selector role="group" aria-label="Access Plans">';
        foreach($plans as $plan){
            $selected=(int)$plan['id']===$default;
            echo '<button type="button" class="selectable-plan'.($selected?' selected':'').'" data-plan-option="'.(int)$plan['id'].'" data-plan-label="'.self::e((string)$plan['name']).'" data-plan-price="'.self::money((int)$plan['effective_price_cents'],(string)$plan['currency']).'" aria-pressed="'.($selected?'true':'false').'"'.(empty($product['can_purchase'])?' disabled':'').'>'
                .(!empty($plan['badge'])?'<span class="plan-badge">'.self::e((string)$plan['badge']).'</span>':'').'<small>'.self::e(strtoupper((string)$plan['name'])).'</small>'.($plan['sale_price_cents']!==null&&$plan['sale_price_cents']<$plan['price_cents']?'<del>'.self::money((int)$plan['price_cents'],(string)$plan['currency']).'</del>':'').'<strong>'.self::money((int)$plan['effective_price_cents'],(string)$plan['currency']).'</strong>'.($plan['saving_percent']===null?'':'<em>Save '.(int)$plan['saving_percent'].'%</em>').'<b>'.((int)$plan['is_lifetime']===1?'Lifetime Access':'Select Plan').'</b></button>';
        }
        if($plans===[])echo '<div class="catalog-empty">No Access Plan is currently available.</div>';
        echo '</div>';
        if($defaultPlan!==null){
            $summary=(string)$defaultPlan['name'].' · '.self::money((int)$defaultPlan['effective_price_cents'],(string)$defaultPlan['currency']);
            echo '<form class="selected-plan-checkout" method="post" action="'.self::url('/checkout/start').'"><input type="hidden" name="csrf" value="'.self::e($csrf).'"><input type="hidden" name="product_slug" value="'.self::e((string)$product['game_slug']).'"><input type="hidden" name="plan_id" value="'.$default.'" data-selected-plan><button class="btn btn-primary btn-large" type="submit"'.(empty($product['can_purchase'])?' disabled':'').'>Buy '.self::e((string)$product['game_name']).' Enhancement <span data-selected-summary>'.self::e($summary).'</span></button></form>';
        }
        if(empty($product['can_purchase']))echo '<p class="purchase-paused">Purchases are currently paused. Existing customers can still use their active Access.</p>';
    }

    private static function compatibility(array $p):void
    {echo '<section class="commerce-section compact-section compatibility-section"><div class="section-intro"><span>COMPATIBILITY</span><h2>Requirements &amp; product details</h2></div><dl><div><dt>Operating System</dt><dd>'.self::e(trim((string)($p['operating_systems']??$p['compatibility']??''))?:'Not specified').'</dd></div><div><dt>Product Status</dt><dd>'.self::statusLabel((string)$p['commercial_status']).'</dd></div><div><dt>Version</dt><dd>'.self::e((string)($p['latest_version']??'Not published')).'</dd></div><div><dt>Last Updated</dt><dd>'.(empty($p['latest_release'])?'Not published':self::date((string)$p['latest_release'])).'</dd></div><div><dt>Authorized Devices</dt><dd>1 active device</dd></div></dl>'.(empty($p['requirements'])?'':'<p>'.nl2br(self::e((string)$p['requirements'])).'</p>').'</section>';}

    private static function owned(array $p):void
    {$a=$p['owned_access']??null;if(!is_array($a))return;$status=(string)$a['status'];$lifetime=(int)($a['is_lifetime']??0)===1||($a['expires_at']===null&&$status==='active');if($lifetime){$label='Lifetime Access';$meta='Your Access does not expire.';}elseif($status==='expired'||(!empty($a['expires_at'])&&strtotime((string)$a['expires_at'])<=time())){$label='Access Expired';$meta='Renew to activate this Enhancement again.';}else{$label='You Own This Enhancement';$meta=empty($a['expires_at'])?'Pending first activation.':'Active until '.self::date((string)$a['expires_at']);}echo '<div class="owned-notice"><strong>'.self::e($label).'</strong><span>'.self::e($meta).'</span><div><a href="'.self::url('/products').'">Open Dashboard</a>'.(($status==='expired')?'<a href="#pricing">Renew Access</a>':'<a href="'.self::url('/documentation').'">Documentation</a><a href="'.self::url('/downloads').'">Download</a><a href="#pricing">Extend Access</a>').'</div></div>';}

    private static function statusRow(string $name,string $status,mixed $incident,mixed $updated,?array $image=null):void
    {echo '<article>'.($image===null?'':self::cover($image,false)).'<div><h2>'.self::e($name).'</h2><p>'.self::e(trim((string)$incident)?:'No active incident.').'</p><small>Last updated '.(is_string($updated)?self::date($updated):'Not reported').'</small></div><span class="commerce-status status-'.self::e($status).'"><i></i>'.self::statusLabel($status).'</span></article>';}
    private static function update(array $u):void{echo '<article class="update-card">'.self::cover(['image_url'=>$u['image_url']??null,'game_name'=>$u['game_name']??'Pericles'],false).'<div><span>'.self::e((string)$u['game_name']).' · '.self::e((string)$u['version']).'</span><h3>'.self::e((string)$u['summary']).'</h3><time>'.self::date((string)$u['published_at']).'</time></div></article>';}
    private static function cover(array $i,bool $large):string{$name=(string)($i['game_name']??$i['name']??'Game');$url=trim((string)($i['image_url']??''));if($url==='')return '<span class="cover-fallback" aria-hidden="true">'.self::e(strtoupper(substr($name,0,2))).'</span>';return '<img '.($large?'':'loading="lazy" ').'src="'.self::e($url).'" alt="'.self::e($name.' cover').'" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="cover-fallback" hidden aria-hidden="true">'.self::e(strtoupper(substr($name,0,2))).'</span>';}

    private static function start(string $title,string $description,?array $user,string $csrf,string $active,bool $hasChangelog=true,bool $withStripe=false):void
    {$fullTitle=str_contains(strtolower($title),'pericles')?$title:$title.' — Pericles';$canonical=self::canonical();header('Content-Type: text/html; charset=utf-8');header('Cache-Control: no-store');echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#100d17"><title>'.self::e($fullTitle).'</title><meta name="description" content="'.self::e($description).'"><link rel="canonical" href="'.self::e($canonical).'"><meta property="og:type" content="website"><meta property="og:title" content="'.self::e($fullTitle).'"><meta property="og:description" content="'.self::e($description).'"><meta property="og:url" content="'.self::e($canonical).'"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Figtree:wght@400;500;600;700&amp;family=Outfit:wght@500;600;700&amp;family=Roboto+Mono:wght@400;500;600&amp;display=swap" rel="stylesheet"><link rel="stylesheet" href="'.self::url('/assets/pericles.css?v=20260905-2').'">'.($withStripe?'<script defer src="https://js.stripe.com/dahlia/stripe.js"></script>':'').'<script defer src="'.self::url('/assets/pericles.js?v=20260905-2').'"></script></head><body class="commerce-page"><header class="commerce-header"><div class="commerce-nav"><a class="brand" href="'.self::url('/').'"><b>P</b><span>Pericles</span></a><button class="commerce-menu-toggle" type="button" data-commerce-menu aria-label="Open navigation">☰</button><nav data-commerce-nav><a class="'.($active==='enhancements'?'active':'').'" href="'.self::url('/enhancements').'">Enhancements</a><a href="'.self::url('/#how-it-works').'">How It Works</a><a class="'.($active==='status'?'active':'').'" href="'.self::url('/status').'">Status</a>'.($hasChangelog?'<a class="'.($active==='changelog'?'active':'').'" href="'.self::url('/changelog').'">Changelog</a>':'').'<a href="'.self::url('/#faq').'">FAQ</a><a class="'.($active==='support'?'active':'').'" href="'.self::url('/support').'">Support</a></nav><div class="commerce-actions">';if($user===null)echo '<a class="btn btn-ghost" href="'.self::url('/login').'">Sign In</a><a class="btn btn-primary" href="'.self::url('/enhancements').'">Explore Enhancements</a>';else{$name=trim((string)($user['display_name']??''))?:explode('@',(string)$user['email'])[0];echo '<a class="btn btn-outline" href="'.self::url('/account').'">Dashboard</a><details class="account-menu public-account-menu"><summary aria-label="Open profile menu"><span class="avatar">'.self::e(strtoupper(substr($name,0,1))).'</span><span class="public-username">'.self::e($name).'</span></summary><div><strong>'.self::e($name).'</strong><small>'.self::e((string)$user['email']).'</small><hr><a href="'.self::url('/activity').'">Activity</a><a href="'.self::url('/billing').'">Billing</a><a href="'.self::url('/account/support').'">Support</a><a href="'.self::url('/settings').'">Profile &amp; Settings</a><a href="'.self::url('/security').'">Security</a><hr><form method="post" action="'.self::url('/logout').'"><input type="hidden" name="csrf" value="'.self::e($csrf).'"><button type="submit">Sign Out</button></form></div></details>';}echo '</div></div></header>';}

    private static function end(?array $user=null,bool $hasChangelog=true):never
    {echo '<footer class="commerce-footer"><div class="footer-grid"><section><a class="brand" href="'.self::url('/').'"><b>P</b><span>Pericles</span></a><p>Premium Game Enhancements delivered through the Pericles platform.</p></section><section><strong>Product</strong><a href="'.self::url('/enhancements').'">Enhancements</a><a href="'.self::url('/status').'">Status</a>'.($hasChangelog?'<a href="'.self::url('/changelog').'">Changelog</a>':'').'</section><section><strong>Resources</strong><a href="'.self::url('/documentation').'">Documentation</a><a href="'.self::url('/#faq').'">FAQ</a><a href="'.self::url('/support').'">Support</a></section><section><strong>Account</strong><a href="'.self::url($user===null?'/login':'/account').'">'.($user===null?'Sign In':'Dashboard').'</a></section><section><strong>Legal</strong><a href="'.self::url('/terms').'">Terms</a><a href="'.self::url('/terms-of-sale').'">Terms of Sale</a><a href="'.self::url('/privacy').'">Privacy Policy</a><a href="'.self::url('/refund-policy').'">Refund Policy</a><a href="'.self::url('/cookies').'">Cookie Policy</a><a href="'.self::url('/legal-notice').'">Legal Notice</a><a href="'.self::url('/disclaimer').'">Disclaimer</a></section></div><div class="footer-bottom"><span>© '.gmdate('Y').' Pericles</span><span>Independent third-party software platform.</span></div></footer></body></html>';exit;}
    private static function statusLabel(string $s):string{return match($s){'operational'=>'Operational','updating'=>'Updating','maintenance'=>'Maintenance','discontinued'=>'Discontinued',default=>'Unavailable'};}
    private static function money(int $c,string $currency):string{$value=number_format($c/100,2,'.',',');return strtoupper($currency)==='EUR'?'€'.$value:$value.' '.self::e(strtoupper($currency));}
    private static function date(string $v):string{$t=strtotime($v);return $t===false?'—':gmdate('M j, Y',$t);}
    private static function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private static function url(string $p):string{$script=str_replace('\\','/',(string)($_SERVER['SCRIPT_NAME']??'/index.php'));$base=rtrim(str_replace('\\','/',dirname($script)),'/.');return self::e(($base===''?'':$base).'/'.ltrim($p,'/'));}
    private static function canonical():string{$https=strtolower((string)($_SERVER['HTTPS']??''))==='on'||(int)($_SERVER['SERVER_PORT']??0)===443;$scheme=$https?'https':'http';$host=preg_replace('/[^A-Za-z0-9.:-]/','',(string)($_SERVER['HTTP_HOST']??'localhost'))?:'localhost';$path=parse_url((string)($_SERVER['REQUEST_URI']??'/'),PHP_URL_PATH)?:'/';return$scheme.'://'.$host.$path;}
}
